-- Données simulées (généré pour la démo) : toute l'équipe part des mêmes lignes.
-- Courbes : indice d'intérêt mensuel 0-100, de décembre 2021 à novembre 2026.

INSERT INTO aromes (ref, nom, metier, notes, description, disponibilite, cout, recolte, risque) VALUES
  ('GIV-T-1042', 'Arôme yuzu', 'taste', ARRAY['agrume', 'zesté', 'acidulé', 'floral', 'japonais'], 'Zeste de yuzu frais, pour boissons et pâtisseries.', 'tendue', 'hausse', 'novembre-décembre', 'Récolte concentrée au Japon et en Corée ; aléas climatiques sur les derniers hivers.'),
  ('GIV-T-1047', 'Arôme sudachi', 'taste', ARRAY['agrume', 'zesté', 'acidulé', 'vert', 'japonais'], 'Petit agrume vert japonais, plus vif que le yuzu.', 'disponible', 'stable', 'août-octobre', 'Production japonaise limitée mais régulière.'),
  ('GIV-T-1051', 'Arôme bergamote', 'taste', ARRAY['agrume', 'floral', 'zesté', 'amer'], 'Bergamote de Calabre, profil floral et légèrement amer.', 'disponible', 'stable', 'novembre-mars', 'Filière italienne bien établie.'),
  ('GIV-T-1055', 'Arôme clémentine', 'taste', ARRAY['agrume', 'sucré', 'fruité', 'zesté'], 'Clémentine juteuse, plus ronde et sucrée.', 'disponible', 'baisse', 'novembre-janvier', 'Approvisionnement méditerranéen abondant.'),
  ('GIV-T-1060', 'Arôme combava', 'taste', ARRAY['agrume', 'zesté', 'vert', 'épicé'], 'Combava, agrume tropical aux notes vertes et citronnelle.', 'tendue', 'hausse', 'toute l''année', 'Volumes faibles, dépend de quelques producteurs à Madagascar.'),
  ('GIV-T-1064', 'Arôme citron de Meyer', 'taste', ARRAY['agrume', 'sucré', 'floral', 'doux'], 'Hybride citron-mandarine, doux et floral.', 'disponible', 'stable', 'décembre-avril', 'Production californienne stable.'),
  ('GIV-T-1188', 'Arôme matcha', 'taste', ARRAY['végétal', 'herbacé', 'amer', 'japonais', 'thé'], 'Thé vert broyé, umami et herbacé.', 'tendue', 'hausse', 'avril-mai', 'Forte demande mondiale : récoltes de première qualité très disputées.'),
  ('GIV-T-1192', 'Arôme thé vert sencha', 'taste', ARRAY['thé', 'végétal', 'herbacé', 'frais'], 'Sencha infusé, plus léger que le matcha.', 'disponible', 'stable', 'avril-juin', 'Filière japonaise et chinoise diversifiée.'),
  ('GIV-T-1310', 'Arôme mangue-piment', 'taste', ARRAY['pimenté', 'fruité', 'sucré', 'épicé'], 'Mangue mûre relevée de piment doux.', 'disponible', 'stable', 'mars-juillet', 'Mangue et piment disponibles auprès de plusieurs origines.'),
  ('GIV-T-1315', 'Arôme miel pimenté', 'taste', ARRAY['sucré', 'pimenté', 'miellé', 'épicé'], 'Miel infusé au piment, pour sauces et snacks.', 'disponible', 'hausse', 'toute l''année', 'Prix du miel en hausse depuis deux ans.'),
  ('GIV-T-1505', 'Arôme pistache torréfiée', 'taste', ARRAY['pistache', 'grillé', 'gourmand', 'lacté'], 'Pistache grillée, beurrée, pour confiserie et chocolat.', 'rare', 'hausse', 'août-septembre', 'Pénurie mondiale de pistaches depuis l''effet Dubai Chocolate.'),
  ('GIV-T-1510', 'Arôme chocolat noir', 'taste', ARRAY['chocolat', 'grillé', 'amer', 'gourmand'], 'Cacao 70 %, notes torréfiées.', 'tendue', 'hausse', 'octobre-mars', 'Cours du cacao historiquement élevés.'),
  ('GIV-T-1520', 'Arôme vanille Bourbon', 'taste', ARRAY['vanillé', 'sucré', 'lacté', 'gourmand'], 'Vanille de Madagascar, crémeuse.', 'tendue', 'stable', 'juin-septembre', 'Dépendance à Madagascar ; cyclones possibles.'),
  ('GIV-T-1525', 'Arôme noisette', 'taste', ARRAY['noisette', 'grillé', 'gourmand', 'sucré'], 'Noisette du Piémont torréfiée.', 'disponible', 'stable', 'août-septembre', 'Filière turque et italienne solide.'),
  ('GIV-F-2201', 'Accord musc blanc', 'fragrance', ARRAY['musqué', 'propre', 'doux', 'poudré'], 'Musc blanc moléculaire, effet seconde peau.', 'disponible', 'stable', 'synthèse', 'Molécule de synthèse, aucun risque matière.'),
  ('GIV-F-2210', 'Accord coton propre', 'fragrance', ARRAY['propre', 'frais', 'aldéhydé', 'doux'], 'Linge propre séché au soleil.', 'disponible', 'stable', 'synthèse', 'Ingrédients de synthèse disponibles.'),
  ('GIV-F-2290', 'Accord pistache-amande', 'fragrance', ARRAY['gourmand', 'pistache', 'grillé', 'lacté'], 'Pistache crémeuse et amande grillée pour parfums gourmands.', 'tendue', 'hausse', 'synthèse et naturel', 'La part naturelle dépend de la pistache, en tension.'),
  ('GIV-F-2330', 'Absolue fleur de sureau', 'fragrance', ARRAY['floral', 'frais', 'miellé', 'vert'], 'Fleur de sureau cueillie en Europe, miellée et verte.', 'rare', 'stable', 'mai-juin', 'Cueillette courte, volumes limités.'),
  ('GIV-B-4410', 'Base « seconde peau » pour soin', 'beauty', ARRAY['propre', 'doux', 'musqué', 'soin'], 'Parfumage discret pour sérums et soins visage.', 'disponible', 'stable', 'synthèse', 'Aucun risque matière identifié.'),
  ('GIV-B-4460', 'Accord lait de riz', 'beauty', ARRAY['lacté', 'doux', 'céréale', 'propre'], 'Lait de riz doux et cotonneux pour soins et cheveux.', 'disponible', 'stable', 'septembre-novembre', 'Riz disponible auprès de nombreuses origines.');

